//! LightCraft on phones: the engine as a native library for the Android app in `android/` (and,
//! later, an iOS app), with bindings generated by [UniFFI](https://mozilla.github.io/uniffi-rs).
//!
//! The phone UI is one more frontend next to the desktop app, the CLI/MCP server and the web build:
//! it runs commands by id ([`MobileSession::execute`]: the same ids and JSON parameters as the
//! control channel and MCP) and asks for pixels ([`MobileSession::render_view`],
//! [`MobileSession::render_thumbnail`], [`MobileSession::export`]). A few typed helpers (photos,
//! develop controls, history) save the UI from parsing JSON for what it shows all the time.
//!
//! Threading: every method may be called from any thread, and the ones that render block, so the
//! UI calls them off its main thread. A render holds the session lock only to set up its job and
//! to keep the decoded source afterwards; the develop work itself runs unlocked, so the UI can keep
//! changing settings while a render is in flight.
#![forbid(unsafe_code)]
#![deny(clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::unimplemented, clippy::todo, clippy::unreachable)]

use std::sync::{Arc, Mutex, MutexGuard, PoisonError};

use lightcraft_engine::catalog::{Flag, MediaKind, Photo, PhotoId};
use lightcraft_engine::develop::{CONTROLS, ControlSpec, Section, Track, Treatment, WbMode, controls};
use lightcraft_engine::pipeline::{Rendered, StageCache};
use lightcraft_engine::presets as engine_presets;
use lightcraft_engine::{EngineError, LibrarySource, RenderJob, Session, catalog, export, memory};
use serde_json::{Value, json};

uniffi::setup_scaffolding!();

/// What went wrong, as a message the user can act on.
#[derive(Debug, thiserror::Error, uniffi::Error)]
#[uniffi(flat_error)]
pub enum MobileError {
    /// A command failed or was refused: unknown id, not available right now, bad parameters…
    #[error("{0}")]
    Command(String),
    /// A photo could not be rendered or exported (unreadable file, unsupported format…).
    #[error("{0}")]
    Render(String),
    /// The library could not be opened (or another process has it open).
    #[error("{0}")]
    Library(String),
    #[error("no photo with id {0}")]
    NoPhoto(u64),
    /// The cloud library could not be reached or used (offline, wrong login, not a LightCraft cloud…).
    #[error("{0}")]
    Cloud(String),
}

impl From<EngineError> for MobileError {
    fn from(e: EngineError) -> Self {
        MobileError::Command(e.to_string())
    }
}

