pub const CURVE_SAMPLES: usize = 129;

/// How a slider track is drawn ([`lightcraft_engine::develop::controls::Track`]).
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Enum)]
pub enum SliderTrack {
    /// Plain track, filled from the minimum.
    Plain,
    /// Plain track, zero in the middle.
    Centered,
    /// Blue → yellow (white balance temperature).
    Temp,
    /// Green → magenta (tint).
    Tint,
    /// Two sRGB hex colours (`#7a7a7a`).
    Gradient { from: String, to: String },
    /// Hue shift of colour mixer band `band` (0 = red … 7 = magenta).
    Hue { band: u8 },
    /// Saturation of a band: grey → band colour.
    Sat { band: u8 },
    /// Luminance of a band: dark → light band colour.
    Lum { band: u8 },
    /// The full hue circle.
    Rainbow,
}

impl From<Track> for SliderTrack {
    fn from(t: Track) -> Self {
        match t {
            Track::Plain => SliderTrack::Plain,
            Track::Centered => SliderTrack::Centered,
            Track::Temp => SliderTrack::Temp,
            Track::Tint => SliderTrack::Tint,
            Track::Gradient { from, to } => SliderTrack::Gradient { from: from.into(), to: to.into() },
            Track::Hue { band } => SliderTrack::Hue { band },
            Track::Sat { band } => SliderTrack::Sat { band },
            Track::Lum { band } => SliderTrack::Lum { band },
            Track::Rainbow => SliderTrack::Rainbow,
        }
    }
}

