/// The connection settings of the cloud library, kept in the library folder (`cloud.json`).
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
struct CloudSettings {
    config_path: String,
    remote: String,
    device: String,
}

/// The engine as the cloud client drives it: every command takes the session lock on its own, so a
/// refresh or a download never holds the UI up.
struct CloudEngine<'a>(&'a MobileSession);

impl lightcraft_cloud_client::Engine for CloudEngine<'_> {
    fn call(&mut self, command: &str, params: Value) -> Result<Value, String> {
        self.0.lock().execute(command, &params).map_err(|e| e.to_string())
    }
}

/// Where librclone is loaded from: `LIGHTCRAFT_LIBRCLONE`, else by name (the app's own libraries on
/// Android); the host build for this crate's tests.
fn librclone_path() -> Option<std::path::PathBuf> {
    if let Some(p) = std::env::var_os("LIGHTCRAFT_LIBRCLONE") {
        return Some(p.into());
    }
    cfg!(test).then(|| std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("librclone-host/librclone.so"))
}

fn cloud_err(e: lightcraft_cloud_client::Error) -> MobileError {
    MobileError::Cloud(e.to_string())
}

/// The engine version (`0.4.0`).
#[uniffi::export]
pub fn engine_version() -> String {
    env!("CARGO_PKG_VERSION").into()
}

/// Send the engine's log to logcat (Android; elsewhere it does nothing). Safe to call repeatedly.
#[uniffi::export]
pub fn init_logging() {
    #[cfg(target_os = "android")]
    android_logger::init_once(android_logger::Config::default().with_max_level(log::LevelFilter::Info).with_tag("LightCraft"));
}

/// One editing session: a library (on disk, or the in-memory demo) and everything done to it.
#[derive(uniffi::Object)]
pub struct MobileSession {
    session: Mutex<Session>,
    /// The editor's intermediate render stages for one photo at a time, its view and its "before"
    /// view each with their own (like the desktop loupe's `Main` and `Before` slots): a slider drag
    /// then only redoes the stages its setting feeds.
    view_stages: Mutex<Option<ViewStages>>,
    /// While a photo is in the editor: where its history starts (a count of the undo steps ever
    /// taken, see `Session::undo_dropped`). The editor's Undo goes no further back, so the
    /// library's own steps (a delete, a restore, an album) stay out of its reach, as in the
    /// reference app.
    edit_floor: Mutex<Option<usize>>,
    /// The sidecars [`MobileSession::sync_folder`] has read, by path: (modified time, size) when it
    /// did. Not the time of the last synchronization: a sync tool keeps the modified time of the
    /// device that wrote a file, so a sidecar can arrive "older" than the last synchronization.
    sidecars_seen: Mutex<std::collections::HashMap<std::path::PathBuf, (std::time::SystemTime, u64)>>,
    /// The cloud library, once connected (see [`MobileSession::cloud_connect`]).
    cloud: Mutex<Option<Arc<lightcraft_cloud_client::CloudLibrary>>>,
    /// Its settings, kept (and in `cloud.json`) while a connection is wanted, even when it failed to load.
    cloud_settings: Mutex<Option<CloudSettings>>,
    /// Why the settings could not be connected (at launch).
    cloud_error: Mutex<Option<String>>,
}

struct ViewStages {
    photo: PhotoId,
    after: Arc<StageCache>,
    before: Arc<StageCache>,
}

impl MobileSession {
    fn wrap(session: Session) -> Self {
        MobileSession {
            session: Mutex::new(session),
            view_stages: Mutex::new(None),
            edit_floor: Mutex::new(None),
            sidecars_seen: Mutex::default(),
            cloud: Mutex::new(None),
            cloud_settings: Mutex::new(None),
            cloud_error: Mutex::new(None),
        }
    }

    /// The library folder, when the library is on disk.
    fn library_dir(&self) -> Option<std::path::PathBuf> {
        self.lock().library.as_ref().filter(|l| l.on_disk).map(|l| l.dir.clone())
    }

    fn cloud_library(&self) -> Result<Arc<lightcraft_cloud_client::CloudLibrary>, MobileError> {
        let c = self.cloud.lock().unwrap_or_else(PoisonError::into_inner).clone();
        c.ok_or_else(|| MobileError::Cloud(self.cloud_error.lock().unwrap_or_else(PoisonError::into_inner).clone().unwrap_or_else(|| "no cloud library is connected".into())))
    }

    /// Load the storage of `settings` and make it the cloud library (nothing is saved).
    fn connect_cloud(&self, settings: &CloudSettings, check: bool) -> Result<(), MobileError> {
        use lightcraft_cloud_client::Remote;
        let dir = self.library_dir().ok_or_else(|| MobileError::Cloud("a cloud library needs the library on disk".into()))?;
        let state = dir.join("cloud");
        let remote = lightcraft_cloud_client::RcloneRemote::open(librclone_path().as_deref(), std::path::Path::new(&settings.config_path), &settings.remote, Some(&state.join("tmp"))).map_err(cloud_err)?;
        if check {
            // (reachable, and a LightCraft cloud)
            remote.list("mobile", false).map_err(|e| match e {
                lightcraft_cloud_client::Error::NotFound(_) => MobileError::Cloud(format!("{} is not a LightCraft cloud library (no mobile/ folder)", settings.remote)),
                e => cloud_err(e),
            })?;
        }
        let lib = lightcraft_cloud_client::CloudLibrary::open(&state, Arc::new(remote), &settings.remote, &settings.device).map_err(cloud_err)?;
        // edits reach the PC through the sidecars the engine writes after each change
        self.run("library.xmpPreferences", json!({"autoWrite": true}))?;
        *self.cloud.lock().unwrap_or_else(PoisonError::into_inner) = Some(Arc::new(lib));
        *self.cloud_settings.lock().unwrap_or_else(PoisonError::into_inner) = Some(settings.clone());
        *self.cloud_error.lock().unwrap_or_else(PoisonError::into_inner) = None;
        Ok(())
    }

    /// At launch: connect again if the library has cloud settings. A failure is kept for `cloud_status`;
    /// the library opens regardless (it works offline from what was downloaded).
    fn restore_cloud(&self) {
        let Some(dir) = self.library_dir() else { return };
        let Some(settings) = std::fs::read(dir.join("cloud.json")).ok().and_then(|b| serde_json::from_slice::<CloudSettings>(&b).ok()) else { return };
        *self.cloud_settings.lock().unwrap_or_else(PoisonError::into_inner) = Some(settings.clone());
        if let Err(e) = self.connect_cloud(&settings, false) {
            *self.cloud_error.lock().unwrap_or_else(PoisonError::into_inner) = Some(e.to_string());
        }
    }

    /// The renders and thumbnails the session holds of `ids` are out of date.
    fn forget_renders(&self, ids: &[u64]) {
        let mut s = self.lock();
        for id in ids {
            s.media.forget(PhotoId(*id));
        }
    }

    fn lock(&self) -> MutexGuard<'_, Session> {
        self.session.lock().unwrap_or_else(PoisonError::into_inner)
    }

    fn run(&self, id: &str, params: Value) -> Result<Value, MobileError> {
        Ok(self.lock().execute(id, &params)?)
    }

    /// Run a look variant's thumbnail job (presets, profiles) as background work.
    fn run_variant(&self, id: u64, job: RenderJob) -> Result<RenderedImage, MobileError> {
        let r = memory::in_background(|| job.run());
        self.lock().accept(&r);
        Ok(rendered_image(id, r.rendered.map_err(MobileError::Render)?, false))
    }

    fn stages_for(&self, photo: PhotoId, before: bool) -> Arc<StageCache> {
        let mut v = self.view_stages.lock().unwrap_or_else(PoisonError::into_inner);
        let stages = match &mut *v {
            Some(s) if s.photo == photo => s,
            other => other.insert(ViewStages { photo, after: Arc::default(), before: Arc::default() }),
        };
        if before { stages.before.clone() } else { stages.after.clone() }
    }

    fn floor(&self) -> MutexGuard<'_, Option<usize>> {
        self.edit_floor.lock().unwrap_or_else(PoisonError::into_inner)
    }

    /// Whether Undo may take back the newest step: in the editor, only the steps since the photo
    /// was opened.
    fn may_undo(&self, s: &Session) -> bool {
        !s.undo.is_empty() && self.floor().is_none_or(|f| s.undo_dropped + s.undo.len() > f)
    }

    /// One pass of the watched folder's scan over its photos, subfolders included (the engine's own
    /// listing is of the folder's top level) → (ids imported, whether files wait for the next
    /// pass). A file is added once its size has stayed the same between two scans, so one still
    /// being copied waits.
    fn scan_folder(&self, folder: &str) -> Result<(Vec<u64>, bool), MobileError> {
        let files = lightcraft_engine::import::expand(&[folder.to_string()], None);
        let listing: Vec<Value> = files.iter().filter_map(|f| Some(json!([f, std::fs::metadata(f).ok()?.len()]))).collect();
        let r = self.run("library.autoImportScan", json!({"listing": listing}))?;
        let imported = r["imported"].as_array().map(|a| a.iter().filter_map(Value::as_u64).collect()).unwrap_or_default();
        let s = self.lock();
        let known: std::collections::HashSet<&str> = s
            .catalog
            .photos()
            .filter_map(|p| match &p.source {
                catalog::Source::File { path } => Some(path.as_str()),
                catalog::Source::Demo { .. } => None,
            })
            .collect();
        let waiting = files.iter().any(|f| !known.contains(f.as_str()) && s.auto_import_seen.get(f) != Some(&u64::MAX));
        Ok((imported, waiting))
    }
}

#[uniffi::export]
impl MobileSession {
    /// A session with the procedural demo library, in memory: nothing is saved.
    #[uniffi::constructor]
    pub fn demo() -> Arc<Self> {
        Arc::new(Self::wrap(Session::with_demo().with_fs().with_system_clock()))
    }

    /// Open the library in folder `dir`, creating it if needed; a new library starts with the
    /// procedural demo photos when `seed_demo` is set. Every change is saved as it is made.
    #[uniffi::constructor]
    pub fn open(dir: String, seed_demo: bool) -> Result<Arc<Self>, MobileError> {
        // a relative path would land wherever the process happens to be (`/` on Android)
        if !std::path::Path::new(&dir).is_absolute() {
            return Err(MobileError::Library(format!("the library folder must be an absolute path, not `{dir}`")));
        }
        // the phone's own time for imports, edits and versions (the engine's default is a fixed test date)
        let mut s = Session::new().with_fs().with_system_clock();
        s.open_library(&dir, seed_demo).map_err(|e| MobileError::Library(e.to_string()))?;
        let session = Arc::new(Self::wrap(s));
        session.restore_cloud();
        Ok(session)
    }

    /// Run command `command` with JSON parameters (`""` = none) and return its JSON result: the
    /// command ids and parameters of the control channel and MCP (`docs/control-protocol.md`).
    pub fn execute(&self, command: String, params_json: String) -> Result<String, MobileError> {
        let params = if params_json.trim().is_empty() {
            Value::Null
        } else {
            serde_json::from_str(&params_json).map_err(|e| MobileError::Command(format!("`{command}`: parameters are not valid JSON: {e}")))?
        };
        Ok(self.run(&command, params)?.to_string())
    }

    /// Every command, with whether it is available right now.
    pub fn commands(&self) -> Vec<CommandEntry> {
        self.lock()
            .commands()
            .into_iter()
            .map(|c| CommandEntry {
                id: c.id.into(),
                label: c.label.into(),
                menu: c.menu.iter().map(|m| m.to_string()).collect(),
                shortcut: c.shortcut.map(str::to_string),
                params: c.params.into(),
                enabled: c.enabled,
                disabled_reason: c.disabled_reason,
            })
            .collect()
    }

    /// The photos of the current view (source, filter and sort), in grid order.
    pub fn photos(&self) -> Vec<PhotoInfo> {
        let mut s = self.lock();
        let (_, ids) = s.visible_shared();
        ids.iter().filter_map(|id| s.catalog.photo(*id)).map(|p| photo_info(p)).collect()
    }

    pub fn photo(&self, id: u64) -> Option<PhotoInfo> {
        self.lock().catalog.photo(PhotoId(id)).map(|p| photo_info(p))
    }

    /// Show photo `id` in the editor: it becomes the one being edited (and the selection), and the
    /// editor's history starts here (its Undo reaches no further back; the library's redo steps go).
    pub fn open_photo(&self, id: u64) -> Result<(), MobileError> {
        self.run("library.select", json!({"ids": [id], "active": id}))?;
        let mut s = self.lock();
        s.redo.clear();
        *self.floor() = Some(s.undo_dropped + s.undo.len());
        Ok(())
    }

    /// Leaving the editor: Undo and Redo reach the whole history again (the library's snackbars).
    pub fn close_editor(&self) {
        *self.floor() = None;
    }

    /// The photo being edited.
    pub fn active_photo(&self) -> Option<u64> {
        self.lock().active().map(|id| id.0)
    }

    /// Every develop slider, in panel order, with the edited photo's values. Photos without an
    /// absolute white balance (see [`RELATIVE_TEMP`]) get the relative Temp slider instead of
    /// `wb.temp`, and Tint on −100..100.
    pub fn develop_controls(&self) -> Vec<DevelopControl> {
        let s = self.lock();
        let photo = s.active().and_then(|id| s.catalog.photo(id));
        let relative = photo.is_some_and(|p| !(p.develops_raw() && !p.relative_wb()));
        let mut d = (*s.active().and_then(|id| s.develop_of(id)).unwrap_or_default()).clone();
        if relative && d.wb.mode == WbMode::AsShot {
            (d.wb.temp, d.wb.tint) = (6500.0, 0.0);
        }
        CONTROLS
            .iter()
            .map(|c| {
                let control = develop_control(c, controls::get(&d, c.id).unwrap_or(c.default));
                match c.id {
                    "wb.temp" if relative => DevelopControl {
                        id: RELATIVE_TEMP.into(),
                        min: -100.0,
                        max: 100.0,
                        default_value: 0.0,
                        step: 1.0,
                        decimals: 0,
                        value: kelvin_to_relative(d.wb.temp),
                        ..control
                    },
                    "wb.tint" if relative => DevelopControl { min: -100.0, max: 100.0, value: d.wb.tint.clamp(-100.0, 100.0), ..control },
                    _ => control,
                }
            })
            .collect()
    }

    /// The edited photo's treatment, white balance mode, profile and optics switches.
    pub fn develop_state(&self) -> Option<DevelopState> {
        let s = self.lock();
        let p = s.catalog.photo(s.active()?)?;
        let d = &p.develop;
        Some(DevelopState {
            black_and_white: d.treatment == Treatment::Bw || d.profile.id == "lc.mono" || d.profile.id.starts_with("lc.bw."),
            wb_mode: enum_id(d.wb.mode),
            profile: d.profile.id.clone(),
            profile_name: engine_presets::profile(&d.profile.id).map_or_else(|| d.profile.id.clone(), |x| x.name.to_string()),
            vignette_style: enum_id(d.vignette.style),
            remove_ca: d.optics.remove_ca,
            lens_corrections: d.optics.lens_profile,
            has_lens_profile: p.embedded_lens.is_some(),
            preview_only: p.preview_only.clone(),
            upright: enum_id(d.geometry.upright),
            constrain_crop: d.geometry.constrain_crop,
        })
    }

    /// Photo counts of the library's views (all, edited, unedited, recently added, deleted) and its
    /// albums, for the title menu. Counting doesn't change the view.
    pub fn library_overview(&self) -> LibraryOverview {
        let s = self.lock();
        let cat = &s.catalog;
        let sort = catalog::Sort::default();
        let count = |source: LibrarySource, edited: Option<bool>| {
            let mut f = source.to_filter(&catalog::Filter::default(), cat);
            f.edited = edited;
            u32::try_from(cat.query(&f, &sort).len()).unwrap_or(u32::MAX)
        };
        let albums = cat
            .albums()
            .map(|a| {
                if a.folder {
                    let inside = cat.albums().filter(|c| c.parent == Some(a.id)).count();
                    return AlbumInfo {
                        id: a.id.0,
                        name: a.name.clone(),
                        count: u32::try_from(inside).unwrap_or(u32::MAX),
                        cover: None,
                        smart: false,
                        parent: a.parent.map(|p| p.0),
                        folder: true,
                    };
                }
                let ids = cat.query(&LibrarySource::Album(a.id).to_filter(&catalog::Filter::default(), cat), &sort);
                AlbumInfo {
                    id: a.id.0,
                    name: a.name.clone(),
                    count: u32::try_from(ids.len()).unwrap_or(u32::MAX),
                    cover: a.cover.filter(|c| ids.contains(c)).or_else(|| ids.first().copied()).map(|c| c.0),
                    smart: a.smart.is_some(),
                    parent: a.parent.map(|p| p.0),
                    folder: false,
                }
            })
            .collect();
        let facet = |name: String, n: usize| Facet { name, count: u32::try_from(n).unwrap_or(u32::MAX) };
        let mut cameras = std::collections::BTreeMap::<String, usize>::new();
        for p in cat.photos().filter(|p| p.in_library() && !p.meta.camera.is_empty()) {
            *cameras.entry(p.meta.camera.clone()).or_default() += 1;
        }
        LibraryOverview {
            cameras: cameras.into_iter().map(|(c, n)| facet(c, n)).collect(),
            keywords: cat.keywords().into_iter().map(|(k, n)| facet(k, n)).collect(),
            people: cat.people().into_iter().map(|p| facet(p.name, p.count)).collect(),
            places: cat.places().into_iter().map(|(k, n)| facet(k, n)).collect(),
            all: count(LibrarySource::All, None),
            edited: count(LibrarySource::All, Some(true)),
            unedited: count(LibrarySource::All, Some(false)),
            recently_added: count(LibrarySource::RecentlyAdded, None),
            deleted: count(LibrarySource::RecentlyDeleted, None),
            albums,
        }
    }

    /// The develop presets: LightCraft's own, then the user's.
    pub fn presets(&self) -> Vec<PresetInfo> {
        self.lock()
            .presets
            .iter()
            .map(|p| PresetInfo { id: p.id.clone(), name: p.name.clone(), group: p.group.clone(), favorite: p.favorite, builtin: p.builtin })
            .collect()
    }

    /// Apply preset `preset` to the edited photo at `amount` percent (0–200; 100 = as made).
    pub fn apply_preset(&self, preset: String, amount: f64) -> Result<(), MobileError> {
        self.run("preset.apply", json!({"id": preset, "amount": if amount.is_finite() { amount } else { 100.0 }}))?;
        Ok(())
    }

    /// Photo `id` with preset `preset` applied on top of its edits, as the desktop's preset browser
    /// previews it: long edge `edge` (16–512), cached by look. Blocks.
    pub fn render_preset_thumbnail(&self, id: u64, preset: String, edge: u32) -> Result<RenderedImage, MobileError> {
        let job = {
            let mut s = self.lock();
            let pr = s.presets.iter().find(|p| p.id == preset).cloned().ok_or_else(|| MobileError::Command(format!("unknown preset `{preset}`")))?;
            let d = s.develop_of(PhotoId(id)).ok_or(MobileError::NoPhoto(id))?;
            let look = pr.apply(&d, 1.0);
            s.variant_job(PhotoId(id), &look, edge as usize).ok_or(MobileError::NoPhoto(id))?
        };
        self.run_variant(id, job)
    }

    /// The colour profiles (`develop.profile` takes their ids): the built-in ones, then those imported.
    pub fn profiles(&self) -> Vec<ProfileEntry> {
        let s = self.lock();
        let builtin = engine_presets::PROFILES.iter().map(|p| ProfileEntry { id: p.id.into(), name: p.name.into(), group: p.group.into() });
        // then the ones imported (`profile.import`: .cube looks), in their own groups
        let imported = s.lut_profiles.iter().map(|p| ProfileEntry { id: p.id.clone(), name: p.name.clone(), group: p.group.clone() });
        builtin.chain(imported).collect()
    }

    /// Photo `id` with profile `profile` in place of its own (the profile browser). Blocks.
    pub fn render_profile_thumbnail(&self, id: u64, profile: String, edge: u32) -> Result<RenderedImage, MobileError> {
        if self.lock().profile_info(&profile).is_none() {
            return Err(MobileError::Command(format!("unknown profile `{profile}`")));
        }
        let job = {
            let mut s = self.lock();
            let mut look = (*s.develop_of(PhotoId(id)).ok_or(MobileError::NoPhoto(id))?).clone();
            look.profile.id = profile;
            s.variant_job(PhotoId(id), &look, edge as usize).ok_or(MobileError::NoPhoto(id))?
        };
        self.run_variant(id, job)
    }

    /// Photo `id` as one of Reset's choices would leave it (`to`: `import`, `default` or
    /// `adjustments`, as `develop.reset` takes them), or, given `settings` (a whole develop-settings
    /// JSON: To Open's), as those; long edge `edge`. Blocks.
    pub fn render_reset_thumbnail(&self, id: u64, to: String, settings: Option<String>, edge: u32) -> Result<RenderedImage, MobileError> {
        let job = {
            let mut s = self.lock();
            let d = s.develop_of(PhotoId(id)).ok_or(MobileError::NoPhoto(id))?;
            let look = match settings {
                Some(json) => {
                    let v: serde_json::Value = serde_json::from_str(&json).map_err(|e| MobileError::Command(format!("settings: {e}")))?;
                    d.merged(&v).map_err(|e| MobileError::Command(format!("settings: {e}")))?
                }
                None => {
                    let to = lightcraft_engine::cmd::ResetTo::parse(&to).ok_or_else(|| MobileError::Command(format!("reset to `{to}`")))?;
                    lightcraft_engine::cmd::reset_settings(&s, PhotoId(id), &d, to)
                }
            };
            s.variant_job(PhotoId(id), &look, edge as usize).ok_or(MobileError::NoPhoto(id))?
        };
        self.run_variant(id, job)
    }

    /// The settings groups (`light`, `whiteBalance`…, as `develop.copy` names them) photo `id` has
    /// changed from how it was imported: Copy Settings' "Modified".
    pub fn modified_groups(&self, id: u64) -> Vec<String> {
        let s = self.lock();
        let Some(d) = s.develop_of(PhotoId(id)) else { return Vec::new() };
        let base = lightcraft_engine::cmd::reset_settings(&s, PhotoId(id), &d, lightcraft_engine::cmd::ResetTo::Import);
        lightcraft_engine::develop::SettingsGroup::ALL
            .into_iter()
            .filter(|g| lightcraft_engine::develop::extract_groups(&d, &[*g]) != lightcraft_engine::develop::extract_groups(&base, &[*g]))
            .filter_map(|g| serde_json::to_value(g).ok().and_then(|v| v.as_str().map(str::to_string)))
            .collect()
    }

    /// Photo `id` with settings `groups` (`light`, `whiteBalance`…, as `develop.pastePrevious` takes
    /// them; none: the copy groups) of the photo edited before it, long edge `edge`. Blocks.
    pub fn render_previous_thumbnail(&self, id: u64, groups: Vec<String>, edge: u32) -> Result<RenderedImage, MobileError> {
        let job = {
            let mut s = self.lock();
            let prev = s.previous_active.filter(|p| *p != PhotoId(id)).ok_or_else(|| MobileError::Command("no previous photo".into()))?;
            let groups: Vec<lightcraft_engine::develop::SettingsGroup> = if groups.is_empty() {
                s.copy_groups.clone()
            } else {
                serde_json::from_value(json!(groups)).map_err(|e| MobileError::Command(format!("groups: {e}")))?
            };
            let partial = lightcraft_engine::develop::extract_groups(&s.develop_of(prev).unwrap_or_default(), &groups);
            let d = s.develop_of(PhotoId(id)).ok_or(MobileError::NoPhoto(id))?;
            let look = lightcraft_engine::develop::apply_partial(&d, &partial, 1.0);
            s.variant_job(PhotoId(id), &look, edge as usize).ok_or(MobileError::NoPhoto(id))?
        };
        self.run_variant(id, job)
    }

    /// Start a slider drag: until [`Self::end_adjustment`], changes are previewed without undo
    /// steps, then committed as one step named `label`.
    pub fn begin_adjustment(&self, label: String) -> Result<(), MobileError> {
        self.run("develop.beginInteraction", json!({"label": label}))?;
        Ok(())
    }

    pub fn end_adjustment(&self) -> Result<(), MobileError> {
        self.run("develop.endInteraction", json!({}))?;
        Ok(())
    }

    /// Set develop control `control` of the edited photo (clamped to its range).
    pub fn set_control(&self, control: String, value: f64) -> Result<(), MobileError> {
        // (JSON has no NaN or infinity: they would arrive as a missing value)
        if !value.is_finite() {
            return Err(MobileError::Command(format!("`{control}`: {value} is not a value")));
        }
        let (control, value) = match control.as_str() {
            RELATIVE_TEMP => ("wb.temp".to_string(), relative_to_kelvin(value)),
            _ => (control, value),
        };
        self.run("develop.set", json!({"control": control, "value": value}))?;
        Ok(())
    }

    /// Put develop control `control` back to its default.
    pub fn reset_control(&self, control: String) -> Result<(), MobileError> {
        let control = if control == RELATIVE_TEMP { "wb.temp".to_string() } else { control };
        self.run("develop.resetControl", json!({"control": control}))?;
        Ok(())
    }

    pub fn history(&self) -> EditHistory {
        let s = self.lock();
        let undo = if self.may_undo(&s) { s.undo.last().map(|u| u.label.clone()) } else { None };
        EditHistory { undo, redo: s.redo.last().map(|u| u.label.clone()) }
    }

    pub fn undo(&self) -> Result<EditHistory, MobileError> {
        let allowed = self.may_undo(&self.lock());
        if allowed {
            self.run("edit.undo", json!({}))?;
        }
        Ok(self.history())
    }

    pub fn redo(&self) -> Result<EditHistory, MobileError> {
        self.run("edit.redo", json!({}))?;
        Ok(self.history())
    }

    /// How far the history reaches (every step taken, the oldest dropped ones too): right after a
    /// step, its mark for [`Self::undo_at`].
    pub fn history_depth(&self) -> u64 {
        let s = self.lock();
        (s.undo_dropped + s.undo.len()) as u64
    }

    /// Undo the step whose mark ([`Self::history_depth`] right after it) is `depth`, if it is still
    /// the newest: a message's Undo takes back what it reported, never a later step. Whether it did.
    pub fn undo_at(&self, depth: u64) -> Result<bool, MobileError> {
        let newest = {
            let s = self.lock();
            (s.undo_dropped + s.undo.len()) as u64 == depth && self.may_undo(&s)
        };
        if newest {
            self.run("edit.undo", json!({}))?;
        }
        Ok(newest)
    }

    /// Take back for good every step after mark `depth` ([`Self::history_depth`] when a tool
    /// opened): its Cancel. They are undone and not left on Redo, and nothing before the photo's
    /// opening is touched.
    pub fn discard_to(&self, depth: u64) -> Result<EditHistory, MobileError> {
        if self.lock().interaction.is_some() {
            self.run("develop.endInteraction", json!({}))?;
        }
        let after = {
            let s = self.lock();
            ((s.undo_dropped + s.undo.len()) as u64).saturating_sub(depth)
        };
        let mut undone = 0usize;
        for _ in 0..after {
            if !self.may_undo(&self.lock()) {
                break;
            }
            self.run("edit.undo", json!({}))?;
            undone += 1;
        }
        let mut s = self.lock();
        let keep = s.redo.len().saturating_sub(undone);
        s.redo.truncate(keep);
        drop(s);
        Ok(self.history())
    }

    /// Add photo files to the library. With `move_files` they are moved into the library's
    /// `Originals/` folder (by capture date) once each copy is verified; otherwise the library
    /// refers to them where they are. A file with the same content as a library photo is skipped
    /// (a duplicate) unless `import_duplicates`.
    pub fn import(&self, paths: Vec<String>, move_files: bool, import_duplicates: bool) -> Result<ImportReport, MobileError> {
        let mut params = json!({"paths": paths});
        if move_files {
            params["mode"] = json!("move");
        }
        if import_duplicates {
            params["duplicates"] = json!("import");
        }
        let r = self.run("library.import", params)?;
        Ok(ImportReport {
            imported: r["imported"].as_array().map(|a| a.iter().filter_map(Value::as_u64).collect()).unwrap_or_default(),
            duplicates: r["duplicates"].as_array().map_or(0, |a| u32::try_from(a.len()).unwrap_or(u32::MAX)),
            existing: r["duplicates"]
                .as_array()
                .map(|a| a.iter().filter_map(|d| d.get("existing").and_then(Value::as_u64)).collect())
                .unwrap_or_default(),
            failed: r["failed"]
                .as_array()
                .map(|a| {
                    a.iter()
                        .map(|f| match (f.get(0).and_then(Value::as_str), f.get(1).and_then(Value::as_str)) {
                            (Some(path), Some(why)) => format!("{path}: {why}"),
                            _ => f.to_string(),
                        })
                        .collect()
                })
                .unwrap_or_default(),
        })
    }

    /// Bring the library up to date with a folder it edits in place (the app's folder library):
    /// photos that appeared in `folder` (or below it) are added, and the edits and metadata of
    /// photos in it are read again from their XMP sidecars when a sidecar is new or changed since
    /// the last call (another app, or a sync tool, wrote it). A sidecar that says what the library
    /// already has changes nothing, and what is read is not written back, so this never rewrites
    /// a sidecar. Needs `library.autoImport` pointed at `folder` (the scan works from it). Blocks
    /// while files that just appeared settle (about a second), so call it off the main thread.
    pub fn sync_folder(&self, folder: String) -> Result<FolderSync, MobileError> {
        let (added, waiting) = self.scan_folder(&folder)?;
        let mut report = FolderSync { added, ..Default::default() };
        if waiting {
            // files seen for the first time: give them a moment instead of waiting for the next launch
            std::thread::sleep(std::time::Duration::from_millis(1200));
            report.added.extend(self.scan_folder(&folder)?.0);
        }
        let root = std::path::Path::new(&folder);
        let stat = |p: &std::path::Path| std::fs::metadata(p).ok().and_then(|m| Some((m.modified().ok()?, m.len())));
        let mut changed = Vec::new();
        {
            let s = self.lock();
            let mut seen = self.sidecars_seen.lock().unwrap_or_else(PoisonError::into_inner);
            for (id, sidecar) in s.existing_sidecars() {
                let under = s.catalog.photo(id).is_some_and(|p| matches!(&p.source, catalog::Source::File { path } if std::path::Path::new(path).starts_with(root)));
                let now = stat(&sidecar);
                if under && now.is_some() && seen.get(&sidecar) != now.as_ref() {
                    if let Some(now) = now {
                        seen.insert(sidecar, now);
                    }
                    changed.push(id);
                }
            }
        }
        report.checked = u32::try_from(changed.len()).unwrap_or(u32::MAX);
        if changed.is_empty() {
            return Ok(report);
        }
        // the command acts on the selection, whatever ids it is given and even when it is empty: borrow it
        let selection = lightcraft_engine::Selection { ids: changed.clone(), active: changed.first().copied() };
        let kept = std::mem::replace(&mut self.lock().selection, selection);
        let r = self.run("photo.readMetadataFromFile", json!({"ids": changed.iter().map(|id| id.0).collect::<Vec<_>>(), "onlyChanged": true}));
        self.lock().selection = kept;
        let r = r?;
        report.updated = r["read"].as_array().map(|a| a.iter().filter_map(|e| e["id"].as_u64()).collect()).unwrap_or_default();
        report.failed = r["failed"]
            .as_array()
            .map(|a| a.iter().map(|e| format!("{}: {}", e["id"], e["error"].as_str().unwrap_or("unreadable"))).collect())
            .unwrap_or_default();
        Ok(report)
    }

    // ---------------------------------------------------------------------------------------
    // cloud library: a PC's published photos on an rclone remote (see docs/cloud-library.md)

    /// Connect the library to a cloud library and remember the settings (`cloud.json` in the library folder;
    /// it connects again at every launch). `config_path` is an rclone config file that holds the remote (the
    /// phone-only one the user imported), `remote` the rclone path of the library (`phone:LightCraft Cloud`,
    /// or `phone:` when the remote's root is the library), `device_name` names this phone in the PC's inbox
    /// (letters, digits, `_`, `-`, `.`; up to 64). Replaces an earlier connection. Checks that the storage can be
    /// reached, so it blocks on the network: call it off the main thread. Also turns on the library's automatic
    /// XMP sidecar writing (edits reach the PC through the sidecars).
    pub fn cloud_connect(&self, config_path: String, remote: String, device_name: String) -> Result<(), MobileError> {
        let dir = self.library_dir().ok_or_else(|| MobileError::Cloud("a cloud library needs the library on disk".into()))?;
        let settings = CloudSettings { config_path, remote: remote.trim().to_string(), device: device_name.trim().to_string() };
        if settings.remote.is_empty() {
            return Err(MobileError::Cloud("name the rclone remote (like `phone:` or `phone:LightCraft Cloud`)".into()));
        }
        self.connect_cloud(&settings, true)?;
        let json = serde_json::to_vec_pretty(&settings).map_err(|e| MobileError::Cloud(e.to_string()))?;
        std::fs::write(dir.join("cloud.json"), json).map_err(|e| MobileError::Cloud(format!("cloud.json: {e}")))?;
        Ok(())
    }

    /// Forget the connection (the settings file). Photos, thumbnails and previews already on the phone stay,
    /// edits not sent yet stay in their sidecars; connecting to the same library again picks up from there.
    pub fn cloud_disconnect(&self) -> Result<(), MobileError> {
        *self.cloud.lock().unwrap_or_else(PoisonError::into_inner) = None;
        *self.cloud_settings.lock().unwrap_or_else(PoisonError::into_inner) = None;
        *self.cloud_error.lock().unwrap_or_else(PoisonError::into_inner) = None;
        if let Some(dir) = self.library_dir() {
            match std::fs::remove_file(dir.join("cloud.json")) {
                Err(e) if e.kind() != std::io::ErrorKind::NotFound => return Err(MobileError::Cloud(format!("cloud.json: {e}"))),
                _ => {}
            }
        }
        Ok(())
    }

    /// Bring the library up to date with the cloud: the photo list (with raw+JPEG pairs listed as two
    /// photos, see `hidden`), thumbnails, and the edits the PC changed, unless an edit here is not sent yet.
    /// Blocks on the network, a few seconds to minutes the first time: call it off the main thread.
    pub fn cloud_refresh(&self) -> Result<CloudRefresh, MobileError> {
        let lib = self.cloud_library()?;
        let r = lib.refresh(&mut CloudEngine(self)).map_err(cloud_err)?;
        let stale: Vec<u64> = r.thumbs.iter().chain(&r.applied).copied().collect();
        self.forget_renders(&stale);
        let n = |v: usize| u32::try_from(v).unwrap_or(u32::MAX);
        Ok(CloudRefresh { total: n(r.total), added: n(r.added), updated: n(r.updated), removed: n(r.removed), hidden: r.hidden, thumbs: r.thumbs, applied: r.applied, blocked: r.blocked, failures: r.failures })
    }

    /// Make photo `photo_id` editable: download its smart preview unless the phone has it, then the editor can
    /// render it (`downloaded`: render again). Blocks on the network. The previews are trimmed to the cache cap, the
    /// least recently opened first.
    pub fn cloud_open(&self, photo_id: u64) -> Result<CloudOpen, MobileError> {
        let lib = self.cloud_library()?;
        let downloaded = lib.ensure_preview(&mut CloudEngine(self), photo_id).map_err(|e| {
            lib.note_error(&e);
            cloud_err(e)
        })?;
        if downloaded {
            self.forget_renders(&[photo_id]);
        }
        Ok(CloudOpen { downloaded })
    }

    /// Download the full-size original of photo `photo_id` (for a full-size export); returns where it is on
    /// the phone. Blocks on the network.
    pub fn cloud_download_original(&self, photo_id: u64) -> Result<String, MobileError> {
        let lib = self.cloud_library()?;
        let path = lib.ensure_original(photo_id).map_err(|e| {
            lib.note_error(&e);
            cloud_err(e)
        })?;
        self.forget_renders(&[photo_id]);
        Ok(path.to_string_lossy().into_owned())
    }

    /// Send the edits not sent yet to the PC's inbox; returns how many went. An edit that could not go (offline)
    /// stays pending. Fails only when something was pending and nothing could be sent. Blocks on the network.
    pub fn cloud_push(&self) -> Result<u32, MobileError> {
        let lib = self.cloud_library()?;
        let r = lib.push_edits(&mut CloudEngine(self)).map_err(cloud_err)?;
        if r.sent == 0 && r.failed > 0 {
            return Err(MobileError::Cloud(r.errors.first().cloned().unwrap_or_else(|| "could not send".into())));
        }
        Ok(u32::try_from(r.sent).unwrap_or(u32::MAX))
    }

    /// The cloud library's state; cheap (no network). Works when nothing is connected (`connected` false).
    pub fn cloud_status(&self) -> CloudStatus {
        let settings = self.cloud_settings.lock().unwrap_or_else(PoisonError::into_inner).clone();
        let Ok(lib) = self.cloud_library() else {
            return CloudStatus {
                remote: settings.as_ref().map(|s| s.remote.clone()).unwrap_or_default(),
                device: settings.map(|s| s.device).unwrap_or_default(),
                cache_cap: lightcraft_cloud_client::DEFAULT_CACHE_CAP,
                last_error: self.cloud_error.lock().unwrap_or_else(PoisonError::into_inner).clone(),
                ..Default::default()
            };
        };
        let _ = lib.pending(&mut CloudEngine(self));
        let st = lib.status();
        let n = |v: usize| u32::try_from(v).unwrap_or(u32::MAX);
        CloudStatus {
            connected: true,
            remote: st.remote,
            device: st.device,
            photos: n(st.photos),
            hidden: n(st.hidden),
            pending_uploads: n(st.pending),
            cache_bytes: st.cache_bytes,
            cache_cap: st.cache_cap,
            last_refresh: st.last_refresh,
            last_error: st.last_error,
        }
    }

    /// Cap the downloaded smart previews at `bytes` (default 2 GiB) and trim to it now.
    pub fn cloud_set_cache_cap(&self, bytes: u64) -> Result<(), MobileError> {
        self.cloud_library()?.set_cache_cap(&mut CloudEngine(self), bytes).map_err(cloud_err)
    }

    /// Which photos are the cloud's and which of them have a preview on the phone; cheap (no network).
    /// Empty when nothing is connected.
    pub fn cloud_photos(&self) -> CloudPhotos {
        self.cloud_library().map(|l| { let (ids, previews) = l.photo_ids(); CloudPhotos { ids, previews, versions: l.content_versions().into_iter().collect() } }).unwrap_or_default()
    }

    /// Photo ids of the partners of raw+JPEG pairs, as of the last refresh: leave them out of the grid.
    pub fn cloud_hidden_photos(&self) -> Vec<u64> {
        self.cloud_library().map(|l| l.hidden_ids()).unwrap_or_default()
    }

    /// Take photo `id` out of the library for good, and delete its file when the library holds it
    /// (under its `Originals/`, where imports by move put them): what the Device tab does with a
    /// gallery photo it opened and that was left untouched. The gallery's own photo stays.
    pub fn discard_photo(&self, id: u64) -> Result<(), MobileError> {
        let file = {
            let s = self.lock();
            let p = s.catalog.photo(PhotoId(id)).ok_or(MobileError::NoPhoto(id))?;
            let originals = s.library.as_ref().filter(|l| l.on_disk).map(|l| l.originals_dir());
            match (&p.source, originals) {
                (catalog::Source::File { path }, Some(dir)) if std::path::Path::new(path).starts_with(&dir) => Some(std::path::PathBuf::from(path)),
                _ => None,
            }
        };
        // housekeeping, not an edit: the selection (by now maybe the next photo in the editor) stays,
        // and Undo doesn't offer it (its file is gone)
        let kept = {
            let mut s = self.lock();
            std::mem::replace(&mut s.selection, lightcraft_engine::Selection::single(PhotoId(id)))
        };
        let r = self.run("photo.deletePermanently", json!({"ids": [id]}));
        {
            let mut s = self.lock();
            if r.is_ok() && s.undo.last().is_some_and(|u| u.label == "Delete Permanently") {
                s.undo.pop();
            }
            s.selection = kept;
            s.selection.ids.retain(|x| x.0 != id);
            if s.selection.active == Some(PhotoId(id)) {
                s.selection.active = s.selection.ids.first().copied();
            }
        }
        r?;
        if let Some(f) = file {
            // a file that can't go stays behind: the photo is out of the library either way
            let _ = std::fs::remove_file(f);
        }
        Ok(())
    }

    /// Take photos `ids` out of the library for good, as Deleted's Delete on the phone: nothing on
    /// the phone takes this back, so the step leaves the history and each photo's file goes with
    /// it when the library holds it (under its `Originals/`, where imports by move put them; left
    /// there, a later import of the same photo got a `-1` name beside it). A file that can't go
    /// stays behind: the photos are out of the library either way. Returns how many went.
    pub fn delete_permanently(&self, ids: Vec<u64>) -> Result<u32, MobileError> {
        let files: Vec<std::path::PathBuf> = {
            let s = self.lock();
            let originals = s.library.as_ref().filter(|l| l.on_disk).map(|l| l.originals_dir());
            ids.iter()
                .filter_map(|&id| {
                    let p = s.catalog.photo(PhotoId(id))?;
                    let dir = originals.as_ref()?;
                    match &p.source {
                        catalog::Source::File { path } if std::path::Path::new(path).starts_with(dir) => Some(std::path::PathBuf::from(path)),
                        _ => None,
                    }
                })
                .collect()
        };
        let r = self.run("photo.deletePermanently", json!({ "ids": ids }))?;
        {
            let mut s = self.lock();
            if s.undo.last().is_some_and(|u| u.label == "Delete Permanently") {
                s.undo.pop();
            }
        }
        for f in files {
            let _ = std::fs::remove_file(f);
        }
        Ok(r.get("deleted").and_then(Value::as_u64).and_then(|n| u32::try_from(n).ok()).unwrap_or(0))
    }

    /// A grid thumbnail of photo `id` with its current look; the long edge is rounded up to 128,
    /// 256, 384 or 512 pixels. Comes from the thumbnail cache when it has one. Blocks.
    pub fn render_thumbnail(&self, id: u64, long_edge: u32) -> Result<RenderedImage, MobileError> {
        let job = self.lock().thumb_job(PhotoId(id), long_edge as usize).ok_or(MobileError::NoPhoto(id))?;
        // grid decodes are background work: they wait while the editor's render needs the memory
        let r = memory::in_background(|| job.run());
        self.lock().accept(&r);
        Ok(rendered_image(id, r.rendered.map_err(MobileError::Render)?, false))
    }

    /// The editor's view of photo `id`, cropped, fitting `max_width × max_height`. `draft` is
    /// faster and a little rougher, for slider drags; `before` shows the photo without its edits;
    /// `mask_overlay` shows that mask over the photo as it asks (the Masking tool's overlay). Blocks.
    pub fn render_view(
        &self,
        id: u64,
        max_width: u32,
        max_height: u32,
        draft: bool,
        before: bool,
        mask_overlay: Option<MaskOverlay>,
    ) -> Result<RenderedImage, MobileError> {
        let photo = PhotoId(id);
        let (w, h) = (max_width.max(1) as usize, max_height.max(1) as usize);
        let job = {
            let mut s = self.lock();
            if before { s.render_job(photo, w, h, true, true) } else { s.loupe_job(photo, w, h, true) }
        }
        .ok_or(MobileError::NoPhoto(id))?
        .with_stages(self.stages_for(photo, before));
        let job = with_mask_overlay(job, mask_overlay);
        let job = if draft { job.draft() } else { job };
        let r = job.run();
        self.lock().accept(&r);
        Ok(rendered_image(id, r.rendered.map_err(MobileError::Render)?, draft))
    }

    /// One window of the editor's view zoomed in: the view as it would look rendered whole at
    /// `frame_width × frame_height` (the photo, cropped, fitting that size), of which only the
    /// `width × height` pixels at `x, y` are rendered, so a zoomed view costs what the screen shows
    /// whatever the zoom. `before` and `mask_overlay` as in [`Self::render_view`]. `None`: what the
    /// window reads (a spot's source, an Auto Mask stroke) is too far from it for one render, so the
    /// whole-frame view has to do. Nothing is cached. Blocks.
    #[allow(clippy::too_many_arguments)]
    pub fn render_view_window(
        &self,
        id: u64,
        frame_width: u32,
        frame_height: u32,
        x: u32,
        y: u32,
        width: u32,
        height: u32,
        before: bool,
        mask_overlay: Option<MaskOverlay>,
    ) -> Result<Option<RenderedImage>, MobileError> {
        let photo = PhotoId(id);
        let (fw, fh) = (frame_width.max(1) as usize, frame_height.max(1) as usize);
        let window = lightcraft_engine::pipeline::PixelWindow { x: x as usize, y: y as usize, w: width.max(1) as usize, h: height.max(1) as usize }
            .clamped(fw, fh);
        let job = {
            let mut s = self.lock();
            if s.catalog.photo(photo).is_none() {
                return Err(MobileError::NoPhoto(id));
            }
            if before { s.region_job_before(photo, fw, fh, window, true) } else { s.region_job(photo, fw, fh, window, true) }
        };
        let Some(job) = job else { return Ok(None) };
        let r = with_mask_overlay(job, mask_overlay).run();
        self.lock().accept(&r);
        Ok(Some(rendered_image(id, r.rendered.map_err(MobileError::Render)?, false)))
    }

    /// Mask `mask` of photo `id` as Masking's column pictures it: what it selects, white on black,
    /// over the photo as cropped, fitting `size × size` (a plain render: the view's caches are left
    /// alone). Blocks.
    pub fn render_mask_thumbnail(&self, id: u64, mask: u32, size: u32) -> Result<RenderedImage, MobileError> {
        let photo = PhotoId(id);
        let mask = u16::try_from(mask).map_err(|_| MobileError::Command(format!("no mask {mask}")))?;
        let n = size.clamp(1, 512) as usize;
        let job = self.lock().render_job(photo, n, n, false, true).ok_or(MobileError::NoPhoto(id))?;
        let job = job
            .with_overlay(lightcraft_engine::pipeline::Overlay::Mask {
                id: mask,
                view: lightcraft_engine::pipeline::MaskView::WhiteOnBlack,
                color: [255, 255, 255],
                opacity: 100,
            })
            .draft();
        let r = job.run();
        self.lock().accept(&r);
        Ok(rendered_image(id, r.rendered.map_err(MobileError::Render)?, true))
    }

    /// Photo `id` with its edits but not its crop or straightening (turned and flipped as the photo
    /// is), for the crop tool to draw the crop over. Fits `max_width × max_height`. Blocks.
    pub fn render_crop_view(&self, id: u64, max_width: u32, max_height: u32, draft: bool) -> Result<RenderedImage, MobileError> {
        let photo = PhotoId(id);
        let (w, h) = (max_width.max(1) as usize, max_height.max(1) as usize);
        let job = self.lock().loupe_job(photo, w, h, false).ok_or(MobileError::NoPhoto(id))?.with_stages(self.stages_for(photo, false));
        let job = if draft { job.draft() } else { job };
        let r = job.run();
        self.lock().accept(&r);
        Ok(rendered_image(id, r.rendered.map_err(MobileError::Render)?, draft))
    }

    /// Guided Upright's guides of photo `id` where the crop tool's view (its edits without the crop or
    /// straightening, [`Self::render_crop_view`]) shows them: `x0, y0, x1, y1` of each, normalized.
    pub fn upright_guides(&self, id: u64) -> Vec<f64> {
        let s = self.lock();
        let Some(p) = s.catalog.photo(PhotoId(id)) else { return Vec::new() };
        let frame = lightcraft_engine::pipeline::geometry::Frame::new(p.width.max(1) as usize, p.height.max(1) as usize, &p.develop, false);
        p.develop
            .geometry
            .guides
            .iter()
            .flat_map(|(a, b)| {
                let (a, b) = (frame.corrected_to_transformed(*a), frame.corrected_to_transformed(*b));
                [a.x, a.y, b.x, b.y]
            })
            .collect()
    }

    /// A point of the crop tool's view of photo `id` (normalized) in the lens-corrected image Guided
    /// Upright keeps its guides in (`[x, y]`; empty when there's no such photo).
    pub fn guide_point(&self, id: u64, x: f64, y: f64) -> Vec<f64> {
        let s = self.lock();
        let Some(p) = s.catalog.photo(PhotoId(id)) else { return Vec::new() };
        if !(x.is_finite() && y.is_finite()) {
            return Vec::new();
        }
        let frame = lightcraft_engine::pipeline::geometry::Frame::new(p.width.max(1) as usize, p.height.max(1) as usize, &p.develop, false);
        let q = frame.transformed_to_corrected(lightcraft_geom::Point::new(x, y));
        vec![q.x, q.y]
    }

    /// The crop of photo `id`, for the crop tool.
    pub fn crop_frame(&self, id: u64) -> Option<CropFrame> {
        let s = self.lock();
        let p = s.catalog.photo(PhotoId(id))?;
        let d = &p.develop;
        let mut frame = lightcraft_engine::pipeline::geometry::Frame::new(p.width.max(1) as usize, p.height.max(1) as usize, d, false);
        frame.crop = d.crop.geometry;
        let corners = frame.crop_quad_norm().iter().flat_map(|q| [q.x, q.y]).collect();
        let r = d.crop.geometry.rect;
        let (aspect_w, aspect_h) = d.crop.aspect.unwrap_or((0, 0));
        Some(CropFrame {
            corners,
            rect: vec![r.x0, r.y0, r.x1, r.y1],
            angle: d.crop.geometry.angle,
            aspect_w,
            aspect_h,
            width: frame.ow,
            height: frame.oh,
        })
    }

    /// The view ↔ photo mapping of photo `id` (its crop, straightening and flips).
    pub fn view_geometry(&self, id: u64) -> Option<ViewGeometry> {
        let s = self.lock();
        let p = s.catalog.photo(PhotoId(id))?;
        let frame = lightcraft_engine::pipeline::geometry::Frame::new(p.width.max(1) as usize, p.height.max(1) as usize, &p.develop, true);
        let (w, h) = frame.native_size();
        let (w, h) = ((w.round() as usize).max(1), (h.round() as usize).max(1));
        let m = frame.out_to_norm(w, h) * lightcraft_geom::Affine::scale(w as f64, h as f64);
        Some(ViewGeometry { to_photo: m.0.to_vec(), width: frame.ow, height: frame.oh })
    }

    /// The Remove spots of photo `id`, and which one is selected.
    pub fn spots(&self, id: u64) -> Vec<SpotInfo> {
        let s = self.lock();
        let Some(p) = s.catalog.photo(PhotoId(id)) else { return Vec::new() };
        p.develop
            .spots
            .iter()
            .map(|sp| SpotInfo {
                mode: enum_id(sp.mode),
                points: sp.points.iter().flat_map(|q| [q.x, q.y]).collect(),
                size: sp.size,
                feather: sp.feather,
                opacity: sp.opacity,
                source: sp.source_offset.map(|o| vec![o.x, o.y]),
            })
            .collect()
    }

    /// The masks of photo `id`, top first.
    pub fn masks(&self, id: u64) -> Vec<MaskInfo> {
        let s = self.lock();
        let Some(p) = s.catalog.photo(PhotoId(id)) else { return Vec::new() };
        p.develop
            .masks
            .iter()
            .map(|m| {
                let first = m.components.first().map(|c| serde_json::to_value(&c.shape).unwrap_or_default()).unwrap_or_default();
                MaskInfo {
                    id: m.id,
                    name: m.name.clone(),
                    visible: m.visible,
                    invert: m.invert,
                    kind: first.get("kind").and_then(Value::as_str).unwrap_or_default().to_string(),
                    shape: first.to_string(),
                    adjust: serde_json::to_string(&m.adjust).unwrap_or_default(),
                    parts: u32::try_from(m.components.len()).unwrap_or(u32::MAX),
                    components: m
                        .components
                        .iter()
                        .map(|c| {
                            let shape = serde_json::to_value(&c.shape).unwrap_or_default();
                            MaskPart {
                                op: enum_id(c.op),
                                kind: shape.get("kind").and_then(Value::as_str).unwrap_or_default().to_string(),
                                shape: shape.to_string(),
                                name: c.name.clone(),
                                hidden: c.hidden,
                                invert: c.invert,
                            }
                        })
                        .collect(),
                }
            })
            .collect()
    }

    /// The mask being edited, if any.
    pub fn selected_mask(&self) -> Option<u32> {
        self.lock().active_mask
    }

    /// The tone curve of photo `id`.
    pub fn tone_curve(&self, id: u64) -> Option<ToneCurveInfo> {
        use lightcraft_engine::cmd::curves::{all_presets, matching_preset};
        let s = self.lock();
        let p = s.catalog.photo(PhotoId(id))?;
        let c = &p.develop.curve;
        let flat = |v: &[lightcraft_geom::Point]| v.iter().flat_map(|q| [q.x, q.y]).collect::<Vec<f64>>();
        // the parametric curve as the renderer models it, sampled evenly over the encoded domain
        let curve = lightcraft_engine::pipeline::curve::ParametricCurve::new(c);
        let last = CURVE_SAMPLES.saturating_sub(1).max(1) as f64;
        let parametric: Vec<f64> = (0..CURVE_SAMPLES).map(|i| curve.at(i as f64 / last)).collect();
        Some(ToneCurveInfo {
            master: flat(&c.master),
            red: flat(&c.red),
            green: flat(&c.green),
            blue: flat(&c.blue),
            parametric,
            preset: matching_preset(&s, c),
            presets: all_presets(&s).into_iter().map(|p| p.name).collect(),
        })
    }

    /// The spot selected for editing (the last one added, or picked), if any.
    pub fn selected_spot(&self) -> Option<u32> {
        self.lock().active_spot.and_then(|i| u32::try_from(i).ok())
    }

    /// Something to show for photo `id` at once while [`Self::render_view`] works: its last view
    /// render for the current settings, else the camera's embedded JPEG (an unedited raw), else a
    /// thumbnail-size render; `None` if there is none. Fits `max_edge`. Blocks, briefly.
    pub fn render_quick_view(&self, id: u64, max_edge: u32) -> Option<RenderedImage> {
        let job = self.lock().quick_view_job(PhotoId(id), max_edge.max(1) as usize, true)?;
        let r = job.run();
        self.lock().accept(&r);
        r.rendered.ok().map(|image| rendered_image(id, image, true))
    }

    /// Get photo `id` ready for the editor in the background, as the desktop does with the photos
    /// next to the one on screen: its source decoded and kept, its view at `max_width × max_height`
    /// rendered and cached, so opening it shows the render at once. Blocks.
    pub fn prefetch_view(&self, id: u64, max_width: u32, max_height: u32) {
        let Some(job) = self.lock().loupe_job(PhotoId(id), max_width.max(1) as usize, max_height.max(1) as usize, true) else { return };
        let r = memory::in_background(|| job.run());
        self.lock().accept(&r);
    }

    /// Let go of the editor's cached render stages (leaving the editor, low memory).
    pub fn release_view(&self) {
        *self.view_stages.lock().unwrap_or_else(PoisonError::into_inner) = None;
    }

    /// Render photo `id` with its edits and encode it as `options_json` asks: the export options of
    /// `app.export` (`{"format": "jpeg", "quality": 90, "longEdge": 2048}`; `""` = full-size JPEG,
    /// quality 90). Nothing is written to disk. Blocks.
    pub fn export(&self, id: u64, options_json: String) -> Result<ExportedFile, MobileError> {
        let o = export_options(&options_json)?;
        let prepared = export::prepare_export(&mut self.lock(), PhotoId(id), &o, 1).map_err(MobileError::Render)?;
        let out = prepared.run().map_err(MobileError::Render)?;
        Ok(ExportedFile {
            mime_type: mime_type(&out.file_name).into(),
            file_name: out.file_name,
            bytes: out.bytes,
            width: u32::try_from(out.width).unwrap_or(u32::MAX),
            height: u32::try_from(out.height).unwrap_or(u32::MAX),
        })
    }

    /// The size photo `id` exports at with `options_json` (as [`Self::export`] reads it), its crop
    /// and the size options applied: what the export sheet shows.
    pub fn export_size(&self, id: u64, options_json: String) -> Result<ImageSize, MobileError> {
        let o = export_options(&options_json)?;
        let s = self.lock();
        let p = s.catalog.photo(PhotoId(id)).ok_or(MobileError::NoPhoto(id))?;
        let (w, h) = export::output_size(p, &o);
        Ok(ImageSize { width: u32::try_from(w).unwrap_or(u32::MAX), height: u32::try_from(h).unwrap_or(u32::MAX) })
    }

    /// Bytes the caches and decodes may use together (the engine's default is a quarter of RAM,
    /// at most 1.5 GB); returns the budget now in effect.
    pub fn set_memory_budget(&self, megabytes: u32) -> u64 {
        self.lock().set_memory_budget((megabytes as usize).saturating_mul(1 << 20)) as u64
    }
}

/// Export options from their JSON (`""` = full-size JPEG, quality 90).
fn export_options(options_json: &str) -> Result<export::ExportOptions, MobileError> {
    let options = if options_json.trim().is_empty() {
        json!({})
    } else {
        serde_json::from_str(options_json).map_err(|e| MobileError::Command(format!("export options are not valid JSON: {e}")))?
    };
    Ok(export::ExportOptions::from_json(&options))
}

/// The Temp slider of photos without an absolute white balance: rendered files (JPEG…) and the
/// raws whose reader has no measured camera illuminant. −100..100 shifts the colour temperature
/// from 6500 K in mireds, as the desktop's Temp slider does for them (`crates/ui-egui/src/panels/edit.rs`).
pub const RELATIVE_TEMP: &str = "wb.tempRel";

fn kelvin_to_relative(k: f64) -> f64 {
    ((1e6 / 6500.0 - 1e6 / k) / 0.8).clamp(-100.0, 100.0)
}

fn relative_to_kelvin(r: f64) -> f64 {
    1e6 / (1e6 / 6500.0 - r.clamp(-100.0, 100.0) * 0.8)
}

fn develop_control(c: &ControlSpec, value: f64) -> DevelopControl {
    DevelopControl {
        id: c.id.into(),
        label: c.label.into(),
        section: section_id(c.section),
        section_label: c.section.label().into(),
        min: c.min,
        max: c.max,
        default_value: c.default,
        step: c.step,
        decimals: c.decimals,
        value,
        track: c.track.into(),
    }
}

/// White balance modes in the Color panel's order (for rendered files it lists As Shot, Auto and
/// Custom only). Custom keeps the white balance in effect; moving Temp or Tint selects it too.
#[uniffi::export]
pub fn white_balance_modes() -> Vec<Choice> {
    WbMode::ALL.iter().map(|m| Choice { id: enum_id(*m), label: m.label().into() }).collect()
}

/// The point curve through `points` (`[x0, y0, x1, y1, …]` in 0..1; fewer than two: a straight
/// line) at `samples` evenly spaced inputs, as the engine applies it: what the Curve tool draws
/// while a point moves.
#[uniffi::export]
pub fn point_curve(points: Vec<f64>, samples: u32) -> Vec<f64> {
    let pts: Vec<(f64, f64)> = points.as_chunks::<2>().0.iter().map(|[x, y]| (*x, *y)).collect();
    let curve = lightcraft_color::spline::MonotoneCurve::new(&pts);
    let n = samples.clamp(2, 4096);
    (0..n).map(|i| curve.eval(f64::from(i) / f64::from(n - 1)).clamp(0.0, 1.0)).collect()
}

/// A unit enum's JSON name (`asShot`, `light`…).
fn enum_id(v: impl serde::Serialize) -> String {
    serde_json::to_value(v).ok().and_then(|v| v.as_str().map(str::to_string)).unwrap_or_default()
}

fn section_id(s: Section) -> String {
    enum_id(s)
}

fn photo_info(p: &Photo) -> PhotoInfo {
    PhotoInfo {
        id: p.id.0,
        file_name: p.file_name.clone(),
        format: p.format.clone(),
        raw: p.kind == MediaKind::Raw,
        width: p.width,
        height: p.height,
        captured: p.captured.clone(),
        rating: p.rating,
        flag: match p.flag {
            Flag::None => PhotoFlag::Unflagged,
            Flag::Pick => PhotoFlag::Pick,
            Flag::Reject => PhotoFlag::Reject,
        },
        edited: p.is_edited(),
        settings_hash: p.develop.hash64(),
        title: p.meta.title.clone(),
        camera: p.meta.camera.clone(),
        lens: p.meta.lens.clone(),
        aspect: shown_aspect(p),
        imported: p.imported.clone(),
        modified: p.edited.clone(),
    }
}

/// Width over height of photo `p` as it is shown: its orientation and crop applied.
fn shown_aspect(p: &Photo) -> f64 {
    let (w, h) = export::output_size(p, &export::ExportOptions::default());
    if w == 0 || h == 0 { 1.0 } else { w as f64 / h as f64 }
}

/// `job` with mask `overlay` drawn over the photo as the masking options ask (the Masking tool's
/// overlay of the mask being edited).
fn with_mask_overlay(job: RenderJob, overlay: Option<MaskOverlay>) -> RenderJob {
    match overlay.and_then(|m| u16::try_from(m.id).ok().map(|id| (id, m))) {
        Some((id, m)) => {
            let [_, r, g, b] = m.color.to_be_bytes();
            job.with_overlay(lightcraft_engine::pipeline::Overlay::Mask {
                id,
                view: lightcraft_engine::pipeline::MaskView::parse(&m.view).unwrap_or_default(),
                color: [r, g, b],
                opacity: m.opacity.min(100),
            })
        }
        None => job,
    }
}

fn rendered_image(photo: u64, r: Rendered, draft: bool) -> RenderedImage {
    let img = r.image;
    RenderedImage {
        photo,
        width: u32::try_from(img.width).unwrap_or(u32::MAX),
        height: u32::try_from(img.height).unwrap_or(u32::MAX),
        rgba: img.data.into_flattened(),
        histogram: ImageHistogram { red: r.histogram.r, green: r.histogram.g, blue: r.histogram.b, luma: r.histogram.luma },
        draft,
    }
}

fn mime_type(file_name: &str) -> &'static str {
    let ext = file_name.rsplit_once('.').map(|(_, e)| e.to_ascii_lowercase()).unwrap_or_default();
    match ext.as_str() {
        "jpg" | "jpeg" => "image/jpeg",
        "png" => "image/png",
        "tif" | "tiff" => "image/tiff",
        "webp" => "image/webp",
        "avif" => "image/avif",
        "jxl" => "image/jxl",
        "dng" => "image/x-adobe-dng",
        _ => "application/octet-stream",
    }
}

